# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# multinomial_lpmf ----
## Setup ----
# 2 years of counts, with a missing value in the second year.
observed <- rbind(c(2, 3, 5), c(NA, 1, 1))
expected_proportion <- rbind(c(0.2, 0.3, 0.5), c(0.2, 0.3, 0.5))

## IO correctness ----
test_that("`multinomial_lpmf()` works with correct inputs", {
  log_probability <- FIMS:::multinomial_lpmf(observed, expected_proportion)
  #' @description Test that the sum of a row of `multinomial_lpmf()` equals `stats::dmultinom()` on the log scale.
  expect_equal(
    object = sum(log_probability[1, ]),
    expected = stats::dmultinom(
      c(2, 3, 5),
      prob = c(0.2, 0.3, 0.5), log = TRUE
    )
  )
})

## Edge handling ----
test_that("`multinomial_lpmf()` returns correct outputs for edge cases", {
  log_probability <- FIMS:::multinomial_lpmf(observed, expected_proportion)
  #' @description Test that `multinomial_lpmf()` skips a row with a missing value, so the row sums to 0.
  expect_equal(
    object = sum(log_probability[2, ]),
    expected = 0
  )
})

## Error handling ----
# No built-in errors to test.
